'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),s=fs.readFileSync('paper-workspace.js','utf8');
const a=s.indexOf('function center('),b=s.indexOf('const isChoice',a),scanStart=s.indexOf('function scan()'),scanEnd=s.indexOf('canvas.addEventListener',scanStart);
assert(a>=0&&b>a&&scanStart>=0&&scanEnd>scanStart);
const formCenter=new Function(s.slice(a,b)+'\nreturn formCenter;')();
const scanCode=s.slice(scanStart,scanEnd);
const types=['single','text','multiple','order','true_false','matching','number','correction','essay'];
const current={layout_version:2,questions:types.map(t=>({type:t}))};
const rows=types.map(t=>{const count=t==='single'||t==='multiple'?4:t==='true_false'?2:0;return {inputs:Array.from({length:count},()=>({checked:false})),row:{classList:{toggle(){}}}};});
const corners=[[0,0],[720,0],[720,1000],[0,1000]],image={width:720,height:1000,data:[]},selected=[[0,1],[2,0],[2,3],[4,1]],marked=new Set(selected.map(([i,j])=>{const [x,y]=formCenter(i,j,types.length,2);return x+','+y;}));
const homography=()=> (x,y)=>[x,y],darkness=(x,y,map)=>marked.has(x+','+y)?0.9:0,updateSave=()=>{},messages=[];
const scan=new Function('current','rows','corners','image','formCenter','darkness','homography','updateSave','$','report',scanCode+'\nreturn scan;')(current,rows,corners,image,formCenter,darkness,homography,updateSave,()=>({checked:false}),(id,msg)=>messages.push(msg));
scan();
assert.deepEqual(rows[0].inputs.map(x=>x.checked),[false,true,false,false]);
assert.deepEqual(rows[2].inputs.map(x=>x.checked),[true,false,false,true]);
assert.deepEqual(rows[4].inputs.map(x=>x.checked),[false,true]);
assert(rows[1].inputs.length===0&&rows[3].inputs.length===0&&rows[5].inputs.length===0,'written rows remain separate');
assert(messages.some(m=>m.includes('3 тестовых вопросов')),'choice count is correct');
console.log('PAPER mixed scan: choice bubbles map to the correct question indices');
